CREATE OR REPLACE FUNCTION poem_compositions_search_vec_trg() RETURNS trigger AS $$
DECLARE
uname text;
BEGIN

  SELECT username INTO uname FROM users WHERE id = NEW.user_id;

  NEW.search_vec :=
    setweight(to_tsvector('simple', f_unaccent(coalesce(NEW.title, ''))), 'A') ||
    setweight(to_tsvector('simple', f_unaccent(coalesce(NEW.pen_name, ''))), 'B') ||
    setweight(to_tsvector('simple', f_unaccent(coalesce(uname, ''))), 'B') ||
    setweight(to_tsvector('simple', f_unaccent(coalesce(NEW.content, ''))), 'C');
  RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_poem_compositions_search_vec ON poem_compositions;
CREATE TRIGGER trg_poem_compositions_search_vec
BEFORE INSERT OR UPDATE OF title, pen_name, content, user_id ON poem_compositions
FOR EACH ROW EXECUTE FUNCTION poem_compositions_search_vec_trg();

DROP TRIGGER IF EXISTS trg_users_refresh_poem_compositions_search_vec ON users;
CREATE TRIGGER trg_users_refresh_poem_compositions_search_vec
AFTER UPDATE OF username ON users
FOR EACH ROW
WHEN (OLD.username IS DISTINCT FROM NEW.username)
EXECUTE FUNCTION users_refresh_poem_compositions_search_vec_trg();
